"""Approved Insurance consolidation, D&D creation, and SC-F9430 account choice."""
from pathlib import Path
import json
import inspect_pysb_historical_invoices as inspection
inspection.OUT=Path(__file__).resolve().parents[6]/'outputs/pysb-invoice-july-supplement-20261014'
from create_pysb_historical_invoice_drafts import Run
from execute_pysb_stock_migration import require,index,rid,save
OUT=inspection.OUT
def main():
 m=Run();manifest=json.loads((OUT/'invoice-draft-manifest.json').read_text(encoding='utf8'));docs={d['source_id']:d for d in manifest['documents']};require(not m.j.get('final_master_exception_resolution'),'Already started: inspect native state before retry');review=json.loads((OUT/'final-exception-master-review.json').read_text(encoding='utf8'));require(all(sum(v.values())==0 for v in review['history_counts'].values()),'Insurance history changed');op={'status':'intent','approved_by':'Bruce','decisions':{'insurance':'Keep richer/history product and archive duplicate','supplier':'Create D&D according to v14','sc_f9430':'Use 6060.00000 then post'},'insurance_before':review['insurance_products']};m.j['final_master_exception_resolution']=op;m.persist()
 # Both have zero historical usage; 114805 has configured accounts, 114806 does not.
 current=m.b.read('product.product',[114805,114806],['active','product_tmpl_id','property_account_expense_id']);require(all(p['active'] for p in current),'Insurance activity changed');tmpl=m.b.call('product.template','read',[[115274]],{'fields':['product_variant_ids'],'context':{'active_test':False}})[0];require(tmpl['product_variant_ids']==[114806],'Other variants would be affected');require(rid(current[0]['property_account_expense_id'])==1989,'Richer account configuration changed');m.mutate('product.template','write',[[115274],{'active':False}]);require(m.b.read('product.product',[114806],['active'])[0]['active'] is False,'Duplicate not archived');m.attach('product.product',[(53853,114805)]);op.update(insurance_keep=114805,insurance_archived=114806);m.persist()
 a=m.a.call('res.partner','fields_get',[],{'attributes':['type','selection','relation']});b=m.b.call('res.partner','fields_get',[],{'attributes':['type','selection','relation']});wanted=['name','vat','ref','is_company','type','street','street2','city','zip','phone','mobile','email','website','country_id','state_id','supplier_rank','customer_rank','identification_type','identification_number','sst_registration_number','ttx_registration_number','vendor_type','property_account_payable_id','property_account_receivable_id','property_supplier_payment_term_id'];source=m.a.read('res.partner',[37735],[k for k in wanted if k in a])[0];require(not m.b.search_read('res.partner',['|',['vat','=',source['vat']],['name','=',source['name']]],['id']),'Supplier already exists: map before creating');vals={k:source[k] for k in wanted if k in source and k in b and not k.endswith('_id')};vals.update(company_id=1,active=True)
 for k in ['identification_type','vendor_type']:
  if vals.get(k) and b[k]['type']=='selection':require(vals[k] in dict(b[k]['selection']),'Supplier selection mismatch')
 country=m.b.search_read('res.country',[['code','=','MY']],['id']);require(len(country)==1,'Country ambiguity');state=m.b.search_read('res.country.state',[['country_id','=',country[0]['id']],['code','=','SGR']],['id']);require(len(state)==1,'State ambiguity');vals.update(country_id=country[0]['id'],state_id=state[0]['id'])
 for field in ['property_account_payable_id','property_account_receivable_id']:
  sid=rid(source[field]);s=m.a.read('account.account',[sid],['code'])[0];ts=m.b.search_read('account.account',[['code','=',s['code'].replace('-','.')],['company_ids','in',[1]]],['active']);require(len(ts)==1 and ts[0]['active'],'Partner account mapping missing');vals[field]=ts[0]['id']
 vals['property_supplier_payment_term_id']=manifest['maps']['account.payment.term'][str(rid(source['property_supplier_payment_term_id']))];op['source_supplier']=source;op['supplier_values']=vals;m.persist();supplier=m.mutate('res.partner','create',[vals],{'context':{'allowed_company_ids':[1]}});op['supplier_target']=supplier;m.persist();actual=m.b.read('res.partner',[supplier],[k for k in vals if b.get(k,{}).get('type')!='many2one']);require(all(actual[0][k]==v for k,v in vals.items() if b.get(k,{}).get('type')!='many2one'),'Supplier data mismatch');m.attach('res.partner',[(37735,supplier)])
 # Correct only the missing document mappings; never regenerate completed manifests.
 manifest['maps']['product.product']['53853']=114805;manifest['maps']['res.partner']['37735']=supplier
 for l in docs[425821]['lines']:
  if l['values'].get('product_id') is None:l['values']['product_id']=114805
 docs[425821]['errors']=[];docs[430385]['header']['partner_id']=supplier;docs[430385]['errors']=[]
 d=docs[430170];rec=m.j['documents'][str(d['source_id'])];line=next(x for x in d['lines'] if x['source_line_id']==1482152);tid=next(x['target_line'] for x in rec['source_line_target_pairs'] if x['source_line']==1482152);old=m.b.read('account.move.line',[tid],['account_id','price_subtotal','price_total','quantity','price_unit'])[0];require(m.b.read('account.move',[rec['target_id']],['state'])[0]['state']=='draft','SC-F9430 already posted');account=m.b.read('account.account',[3851],['code','active'])[0];require(account['code']=='6060.00000' and account['active'],'Approved account unavailable');m.mutate('account.move.line','write',[[tid],{'account_id':3851}]);new=m.b.read('account.move.line',[tid],list(old.keys()))[0];require(all(new[k]==old[k] for k in old if k!='account_id'),'Commercial data changed');line['values']['account_id']=3851;line['approved_account_mapping']={'code':'6060.00000','approved_by':'Bruce'};d['errors']=[];save(OUT/'invoice-draft-manifest.json',manifest);op.update(status='verified',sc_f9430_before=old,sc_f9430_after=new);m.persist();print(json.dumps({'insurance_keep':114805,'insurance_archived':114806,'supplier_target':supplier,'sc_f9430_account':'6060.00000'}))
if __name__=='__main__':main()
